  .options b { color: var(--text-primary); }
  .control { min-width: 56px; padding: 4px 7px; background: var(--bg-base); border: 1px solid var(--border-default); border-radius: var(--radius-sm); color: var(--text-primary); font-variant-numeric: tabular-nums; }
  .workspace { min-height: 0; display: grid; grid-template-columns: 44px minmax(430px,1fr) 272px; }
  .tool-rail { padding: 6px 4px; display: grid; align-content: start; grid-template-columns: repeat(2,18px); grid-auto-rows: 26px; gap: 2px; background: var(--bg-elevated); border-right: 1px solid var(--border-default); }
  .tool { display: grid; place-items: center; border-radius: var(--radius-sm); color: var(--text-secondary); font-size: 12px; }
